import sys
import re


def main():
    text = sys.stdin.read()
    env = {}
    # Match "name <- value;" where value is an integer literal or a variable name.
    pattern = re.compile(r'^\s*([A-Za-z_]\w*)\s*<-\s*(-?\d+|[A-Za-z_]\w*)\s*;?\s*$')

    for raw in text.splitlines():
        line = raw.strip()
        # Skip blank lines and comments.
        if not line or line.startswith('//'):
            continue
        # Strip any trailing comment on the same line.
        if '//' in line:
            line = line.split('//', 1)[0].strip()
            if not line:
                continue
        m = pattern.match(line)
        if not m:
            continue
        name, val = m.group(1), m.group(2)
        if re.fullmatch(r'-?\d+', val):
            env[name] = int(val)
        else:
            env[name] = env.get(val, 0)

    order = list("abcdefghijklmnop") + ["TMP"]
    out = " ".join(f"{v} ?= {env.get(v, 0)};" for v in order)
    print(out)


if __name__ == "__main__":
    main()
